<script setup lang="ts">
import{computed,onBeforeUnmount,onMounted,ref}from"vue";import{ElMessage}from"element-plus";import{MagicStick,Refresh,ArrowDown,ArrowRight}from"@element-plus/icons-vue";import{api}from"@/api";import{consumeSse}from"@/utils/sse";import{useUserStore}from"@/stores/user";import{err,fmt}from"@/utils/format";import type{GrowthResponse,GrowthResult}from"@/types/api";import PageHeader from"@/components/common/PageHeader.vue";import StateView from"@/components/common/StateView.vue";import SectionPanel from"@/components/common/SectionPanel.vue";
const user=useUserStore(),target=ref(''),result=ref<GrowthResponse|null>(null),loading=ref(true),running=ref(false),error=ref(''),stream=ref(''),activeStage=ref(0),activeTab=ref('roadmap'),expandedGap=ref('');const currentStage=computed(()=>result.value?.result.learning_roadmap?.[activeStage.value]);let controller:AbortController|undefined;async function load(){loading.value=true;error.value='';try{const h=await api.growths(user.userId!);if(h[0]){result.value=await api.growthDetail(h[0].id);target.value=result.value.target_job}}catch(e){error.value=err(e)}finally{loading.value=false}}async function run(){if(!target.value.trim()){ElMessage.warning('请填写目标岗位');return}running.value=true;stream.value='';error.value='';activeStage.value=0;activeTab.value='roadmap';expandedGap.value='';controller?.abort();controller=new AbortController();try{await consumeSse<GrowthResult>('/stream/growth',{user_id:user.userId,target_job:target.value},{chunk:x=>stream.value+=x,error:m=>{throw new Error(m)}},controller.signal);result.value=await api.growth({user_id:user.userId,target_job:target.value});ElMessage.success('成长规划生成完成')}catch(e){if((e as Error).name!=='AbortError')ElMessage.error(err(e))}finally{running.value=false}}function selectStage(index:number){activeStage.value=index;activeTab.value='roadmap'}function toggleGap(skill:string){expandedGap.value=expandedGap.value===skill?'':skill}onMounted(load);onBeforeUnmount(()=>controller?.abort());
</script><template><div><PageHeader title="个人就业成长规划" description="根据就业画像与目标岗位，生成阶段化的能力提升路线。"><el-input v-model="target" placeholder="目标岗位（必填）" class="target-input"/><el-button type="primary" :icon="result?Refresh:MagicStick" :loading="running" @click="run">{{result?'重新生成':'生成规划'}}</el-button></PageHeader><div v-if="running" class="stream-panel"><el-icon class="is-loading"><Refresh/></el-icon><b>AI正在制定成长路径</b><pre>{{stream.slice(-1200)||'正在读取档案与知识资源...'}}</pre></div><StateView :loading="loading" :error="error" :empty="!result" empty-text="暂无成长规划" @retry="load"><template #content><div class="growth-head"><div><span>目标岗位</span><h2>{{result?.target_job}}</h2><p>{{result?.result.current_situation}}</p></div><div><span>预计达标时间</span><strong>{{result?.result.expected_timeline}}</strong><small>{{fmt(result?.created_at)}}</small></div></div><div class="growth-tabs" role="tablist"><button class="growth-tab" :class="{'is-active':activeTab==='roadmap'}" type="button" @click="activeTab='roadmap'">阶段路线</button><button class="growth-tab" :class="{'is-active':activeTab==='projects'}" type="button" @click="activeTab='projects'">推荐实战项目 <span>{{result?.result.recommended_projects?.length||0}}</span></button><button class="growth-tab" :class="{'is-active':activeTab==='interview'}" type="button" @click="activeTab='interview'">面试准备 <span>{{result?.result.interview_prep_tips?.length||0}}</span></button></div><div v-if="activeTab==='roadmap'" class="growth-layout"><SectionPanel title="阶段学习路线"><div class="interactive-hint">点击阶段查看重点任务和里程碑</div><el-timeline><el-timeline-item v-for="(s,i) in result?.result.learning_roadmap" :key="s.stage" :timestamp="`阶段 ${i+1}`" placement="top"><button class="timeline-card" :class="{'is-active':activeStage===i}" type="button" @click="selectStage(i)"><h4>{{s.stage}}</h4><p>{{s.focus}}</p><div class="timeline-preview">{{s.tasks?.length||0}} 项任务 · {{s.milestone}}</div></button></el-timeline-item></el-timeline></SectionPanel><div><SectionPanel title="当前阶段任务"><div v-if="currentStage" class="stage-detail"><h3>{{currentStage.stage}}</h3><p>{{currentStage.focus}}</p><ul><li v-for="x in currentStage.tasks" :key="x">{{x}}</li></ul><div class="milestone">里程碑：{{currentStage.milestone}}</div></div><div v-else class="empty-inline">暂无阶段数据</div></SectionPanel><SectionPanel title="能力缺口"><div class="interactive-hint">点击条目展开详情</div><button v-for="g in result?.result.ability_gaps" :key="g.skill" class="gap-item" :class="{'is-expanded':expandedGap===g.skill}" type="button" @click="toggleGap(g.skill)"><div><b>{{g.skill}}</b><el-tag size="small" :type="g.importance==='必须'?'danger':'warning'">{{g.importance}}</el-tag><el-icon class="gap-chevron"><ArrowDown v-if="expandedGap===g.skill"/><ArrowRight v-else/></el-icon></div><span>学习难度：{{g.difficulty}}</span><p v-if="expandedGap===g.skill">{{g.description}}</p></button></SectionPanel><SectionPanel title="推荐学习资源"><ul class="result-list"><li v-for="x in result?.result.recommended_resources" :key="x">{{x}}</li></ul></SectionPanel></div></div><div v-else-if="activeTab==='projects'" class="single-column-content"><SectionPanel title="推荐实战项目"><div class="project-list"><article v-for="project in result?.result.recommended_projects" :key="project.name" class="project-item"><div class="project-heading"><h3>{{project.name}}</h3><el-tag size="small">{{project.difficulty}}</el-tag></div><p>{{project.description}}</p><div class="tech-stack"><el-tag v-for="tech in project.tech_stack" :key="tech" size="small" effect="plain">{{tech}}</el-tag></div></article><div v-if="!result?.result.recommended_projects?.length" class="empty-inline">暂无推荐项目</div></div></SectionPanel></div><div v-else class="single-column-content"><SectionPanel title="面试准备"><div class="interview-tips"><div v-for="(tip,i) in result?.result.interview_prep_tips" :key="tip" class="interview-tip"><span>{{String(i+1).padStart(2,'0')}}</span><p>{{tip}}</p></div><div v-if="!result?.result.interview_prep_tips?.length" class="empty-inline">暂无面试建议</div></div></SectionPanel></div></template></StateView></div></template>
